<?php
require_once __DIR__.'/db.php';require_once __DIR__.'/includes/functions.php';require_role(['admin','manager']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$num=trim($_POST['number']??'');$faculty=trim($_POST['faculty']??'');$group=trim($_POST['group']??'');$course=(int)($_POST['course']??1);
try{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO users(full_name,username,email,password_hash,role) VALUES(?,?,?,?,'student')");$st->execute([$name,$username,$email,password_hash($pass,PASSWORD_DEFAULT)]);$uid=$pdo->lastInsertId();$st=$pdo->prepare("INSERT INTO students(user_id,student_number,faculty,study_group,course) VALUES(?,?,?,?,?)");$st->execute([$uid,$num,$faculty,$group,$course]);$pdo->commit();flash('Донишҷӯ илова шуд.');redirect('students.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Маълумот такрорӣ ё нодуруст аст.';}}
$pageTitle='Иловаи донишҷӯ';require __DIR__.'/includes/header.php';?>
<div class="panel"><h1>Иловаи донишҷӯ</h1><?php if($error):?><div class="alert error"><?=$error?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>">
<?php foreach(['name'=>'Ному насаб','username'=>'Username','email'=>'Email','number'=>'Рақами донишҷӯӣ','faculty'=>'Факултет','group'=>'Гурӯҳ','password'=>'Парол'] as $k=>$v):?><div class="field"><label><?=$v?></label><input name="<?=$k?>" <?=$k==='password'?'type="password"':''?> required></div><?php endforeach;?>
<div class="field"><label>Курс</label><input type="number" name="course" min="1" max="6" value="1" required></div><button>Сабт кардан</button></form></div><?php require __DIR__.'/includes/footer.php';?>
